      "enum": [
       "observed_fact",
       "inferred_claim"
      ]
     },
     "record_ids": {
      "type": "array",
      "items": {
       "type": "string"
      }
     }
    }
   }
  },
  "known_telemetry_limitations": {
   "type": "array",
   "items": {
    "type": "string"
   }
  },
  "claims_not_established": {
